mapper.sql:
(
    u.user_idx = #{viewerUserIdx}
    OR u.user_idx IN (
        SELECT u2.user_idx
        FROM user_mst u2
        WHERE u2.dept_idx IN (
            SELECT target_dept_idx
            FROM team_view_permission
            WHERE viewer_user_idx = #{viewerUserIdx}
              AND can_view = 'Y'
        )
    )
)

mapper.delete:
DELETE FROM activity_plan_store
WHERE assignee_user_idx = #{assigneeUserIdx}
  AND plan_date = #{planDate}

mapper.insert:
INSERT INTO activity_plan_store (
    assignee_user_idx, plan_date, store_idx, sort_order, created_by
) VALUES (
    #{assigneeUserIdx},
    #{planDate},
    #{storeIdx},
    #{sortOrder},
    #{createdBy}
)
